EN = {
 "ui": {"updated": "Last updated", "lang": "Language", "nav": {"privacy": "Privacy", "terms": "Terms", "support": "Support", "delete-account": "Delete account"},
        "home_title": "KXQ legal & help", "home_lead": "Everything about how KXQ — Pack Rip Club handles your account, your packs and your data, in plain words.",
        "footer_tag": "Rip it. Own it. Flip it.", "footer_op": "KXQ® Pack Rip Club is operated by TJ NOVA LTD, registered in England & Wales, company no. 17308318, 124-128 City Road, London EC1V 2NX, United Kingdom.", "contact": "Contact"},
 "privacy": {"title": "Privacy Policy", "lead": "What KXQ collects, why, where it goes and how to erase it.", "sections": [
  ("Who we are", ["KXQ — Pack Rip Club (\"KXQ\", \"we\") is an iPhone app for opening digital packs of collectible cards and toys. The data controller is TJ NOVA LTD, 124-128 City Road, London EC1V 2NX, United Kingdom. Questions: info@tjnovaltd.com."]),
  ("Preview status", ["KXQ is currently in preview. Pack purchases go through a demonstration Apple Pay flow and nobody is charged, pack results are scripted demonstrations, the wallet shown in the app uses the Solana devnet test network, and no physical items are shipped yet. We will update this page before any of that changes."]),
  ("Account data", ["You can browse without an account. If you sign in with Apple, Google or email, we keep: your email address (or Apple's private relay address), the name you choose to share, an account ID, the identifier Apple or Google returns for your sign-in, a salted hash of your password if you set one (never the password itself), your language, and your active sessions (device type, approximate IP address and expiry). Sessions expire after 7 days of inactivity.",
                    "Accounts are run on TJ NOVA LTD's own account service (TJBase), hosted on Cloudflare. One-time sign-in codes are sent by email through our mail provider and expire after 10 minutes."]),
  ("Packs, collection and marketplace", ["Your pack history, revealed items, vault contents, watch list and any marketplace listings you create are stored on your iPhone in this preview. When syncing is switched on in a later version they will be linked to your account so you can restore them on a new device.",
                    "If physical redemption opens, we will ask for a shipping name, address and phone number only when you request a shipment, and use them only to deliver that item."]),
  ("Wallet and blockchain", ["KXQ shows a Solana wallet address for your collection. Public addresses and on-chain records are public by design and cannot be changed or deleted by us or anyone else. To show a balance, the app sends that public address to a public Solana RPC endpoint (api.devnet.solana.com during preview). KXQ never asks for, stores or sends a seed phrase or private key."]),
  ("Payments", ["Payments in KXQ use Apple Pay or the App Store. Card details are handled by Apple and your bank; we never see your full card number. During preview the Apple Pay sheet is a demonstration and no money moves."]),
  ("AI price notes", ["Price figures in KXQ are calculated on your device from demonstration market data. An optional AI price note is not switched on in the current version. If we enable it, it will use Cloudflare Workers AI (Cloudflare, Inc.), it will receive only the item's name, set and grade — never your account details — and under Cloudflare's Workers AI terms the input and output are not kept or used to train models. Estimates are not financial advice."]),
  ("What we do not do", ["No advertising SDKs, no cross-app tracking, no third-party analytics, no sale or sharing of personal data. Live Activities, widgets and haptics run on your device."]),
  ("Security records", ["Our servers on Cloudflare see IP addresses and request metadata to deliver the service and block abuse. The account service keeps a security log of account events (time, action, account ID and IP address). These records are kept only as long as needed for security, fraud prevention and legal obligations."]),
  ("Legal bases and retention", ["We use account data to provide the service you ask for (contract), and security logs for our legitimate interest in keeping KXQ safe. Account data is kept until you delete your account. On deletion we erase your email address, name, password hash, sign-in identifiers and sessions at once; what remains is an anonymous account ID and the security log described above. Records we must keep by law (for example transaction records once real payments exist) are kept only for the required period."]),
  ("Your rights", ["Under UK GDPR you can ask for access, correction, deletion, restriction, portability, or object to processing. Email info@tjnovaltd.com from your account email. You may complain to the UK Information Commissioner's Office (ico.org.uk)."]),
  ("Age", ["KXQ is for adults aged 18 or over. We do not knowingly collect data from anyone under 18; if you believe a minor has an account, tell us and we will delete it."]),
  ("International transfers", ["Cloudflare processes data on its global network. Where data leaves the UK we rely on the UK International Data Transfer Addendum or an adequacy decision."]),
  ("Changes", ["We will post changes here and update the date above. Material changes will also be shown in the app."]),
 ]},
 "terms": {"title": "Terms of Use", "lead": "The rules for using KXQ. This is also the end user licence agreement (EULA) for the iOS app.", "sections": [
  ("Agreement", ["By using KXQ you agree to these terms, Apple's Standard Licensed Application End User License Agreement, and our Privacy Policy. KXQ is provided by TJ NOVA LTD. Apple is not responsible for KXQ or its content."]),
  ("Eligibility", ["You must be 18 or older and legally able to enter a contract. KXQ is not available where pack-style or chance-based purchases are prohibited, and you must not use it there. You are responsible for following the laws where you live."]),
  ("Preview", ["KXQ is in preview. Purchases are demonstrations with no charge, pack results are scripted, the wallet uses a test network, and items shown have no cash value. Features may change or stop without notice."]),
  ("Packs and draws", ["Packs reveal collectible items at random according to the odds shown before you buy. Draws are for entertainment and collecting. They are not gambling, an investment or a way to make money, and no item is guaranteed to hold or gain value. Odds tables add up to 100% and are displayed for every pack."]),
  ("Digital items", ["Each revealed item is a digital record of a physical collectible held in a partner vault. When live, ownership records may be written to the Solana blockchain. You receive a licence to view, hold, list and redeem items inside KXQ; we keep all rights in the app, brand and artwork. Blockchain records are public and permanent."]),
  ("Marketplace", ["You may list items for other KXQ users where the marketplace is available. You must own what you list, set a fair description, and not manipulate prices or trade with yourself. Fees, if any, are shown before you confirm. We may remove listings that break these terms."]),
  ("Redemption and shipping", ["When redemption opens, you may ask for the physical item behind a digital item to be shipped to you. Redemption retires the digital record. Shipping costs, duties and delivery times are shown before you confirm. Some items cannot be shipped to some countries."]),
  ("Payments and refunds", ["Payments are processed by Apple. Refund requests for App Store purchases go through Apple (reportaproblem.apple.com). Statutory consumer rights are not affected."]),
  ("Live rips", ["Live streams are for entertainment. Be respectful in chat; we may remove content or accounts that harass others or break the law."]),
  ("Your account", ["Keep your sign-in secure and tell us about unauthorised use. You can delete your account at any time in the app or by email (see Delete account). We may suspend accounts used for fraud, abuse or to evade these terms."]),
  ("Acceptable use", ["Do not reverse engineer, scrape, attack or overload KXQ, use bots, or use KXQ for money laundering or any illegal purpose."]),
  ("Liability", ["KXQ is provided as is during preview. Nothing in these terms limits liability for death or personal injury caused by negligence, fraud, or anything that cannot be limited by law. Otherwise our total liability is limited to the amount you paid us in the 12 months before the claim."]),
  ("Governing law", ["These terms are governed by the laws of England and Wales, and the courts of England and Wales have jurisdiction, without removing protections you have under the law of the country where you live."]),
  ("Contact", ["TJ NOVA LTD, 124-128 City Road, London EC1V 2NX, United Kingdom — info@tjnovaltd.com."]),
 ]},
 "support": {"title": "Support", "lead": "Stuck on a rip? We answer every message.", "sections": [
  ("Contact", ["Email info@tjnovaltd.com with your account email, device model and iOS version. We reply within 2 business days (UK time)."]),
  ("Sign-in", ["You can sign in with Apple, Google or email. If an email code does not arrive within a few minutes, check spam and request a new code; each code lasts 10 minutes."]),
  ("Purchases", ["During preview, Apple Pay is a demonstration and you are never charged. For App Store charges in a future version, refunds are handled by Apple at reportaproblem.apple.com."]),
  ("Packs, vault and marketplace", ["Pack odds are shown on each pack before you open it. Revealed items appear in your Vault. Preview items have no cash value and cannot be redeemed yet."]),
  ("Wallet", ["The wallet shown in KXQ uses the Solana devnet test network in preview. We will never ask for a seed phrase or private key — anyone who does is not us."]),
  ("Language", ["KXQ follows your iPhone's language. To change it, open Settings › Apps › KXQ › Language on your iPhone."]),
  ("Delete your data", ["See the Delete account page for in-app and email options."]),
 ]},
 "delete-account": {"title": "Delete your account", "lead": "How to permanently remove your KXQ account and data.", "sections": [
  ("In the app", ["Open KXQ › Profile › Account › Delete account and confirm. Your account, sessions and the data linked to it are removed straight away and you are signed out on every device."]),
  ("By email", ["If you cannot open the app, email info@tjnovaltd.com from the email address on your account with the subject \"Delete my KXQ account\". We confirm and complete deletion within 30 days."]),
  ("What is deleted", ["Your email address, name, sign-in identifiers, password hash, sessions, and any synced pack history, vault, watch list and listings. Data stored only on your iPhone is removed when you delete the app. An anonymous account ID and the security log of account events (time, action, IP address) are kept for fraud prevention, as explained in the Privacy Policy."]),
  ("What cannot be deleted", ["Public blockchain records (for example a wallet address or an ownership record already written on-chain) cannot be changed by anyone. Records we must keep by law, such as transaction records once real payments exist, are kept only for the legally required period."]),
  ("Sign in with Apple", ["If you used Sign in with Apple, we also revoke KXQ's access with Apple when you delete your account. You can review it in iPhone Settings › your name › Sign in with Apple."]),
 ]},
}
